/**
 * KS-835 (gateway side) — what the scope gate READS off a bearer token.
 *
 * The auth side (services/auth ks835-oauth-mint-carries-granted-scope.test.ts)
 * proves what an OAuth-minted token CARRIES: `scopes` = the granted list and
 * `authMethod: 'oauth'`. This file proves the gate does the right thing with
 * exactly that shape, and pins the two things the ticket's chain rested on:
 *
 *   · the short-circuit in `requireScope` is keyed on the label — a token
 *     labelled 'oauth' is gated on its `scopes`, a login token (no label /
 *     'jwt' / 'email') is not, by design (RBAC governs logins);
 *   · `attachScopes` — the ticket's "dead bridge" — parsed a singular `scope`
 *     claim nothing mints. It now leaves a token's `scopes` array alone and
 *     accepts the legacy string form only when no array is present, and says
 *     so; the cell here pins both arms so the middleware cannot silently return
 *     to reading a claim that does not exist.
 *
 * The tokens are RS256, signed with the setup file's test private key (the
 * public half is JWT_PUBLIC_KEY, which the middleware verifies against), in the
 * claim SHAPE jwt.ts mints — the cross-service coupling is by claim name, and
 * is named as NOT covered by a single run in both files. The `sk_*` control
 * drives the same route through the API-key path so the gate's 403 for a narrow
 * OAuth token is shown to be the gate working, not the route being broken.
 *
 * Tokens carry no `sessionId`, so the KS-257 session-revocation lookup (Redis)
 * is not in the path; it is orthogonal to what is asserted here.
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach, vi } from 'vitest';
import express from 'express';
import jwt from 'jsonwebtoken';
import type { Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import { configureAuth, authenticateToken, apiKeyCache } from '../middleware/auth';
import { attachScopes, requireScope } from '../middleware/scopes';

// The middleware reaches the security service through the global fetch; the
// harness talks to its own listener through the REAL one, captured first.
const realFetch = globalThis.fetch;
const fetchMock = vi.fn();
vi.stubGlobal('fetch', fetchMock);

let server: Server;
let base: string;

function sign(claims: Record<string, unknown>): string {
  const privatePem = process.env.__TEST_JWT_PRIVATE_PEM as string;
  return jwt.sign(
    { userId: 'user-835', email: 'u835@secuura.local', role: 'OWNER', verificationLevel: 'BASIC', type: 'access', tenantId: 'ten-1', ...claims },
    privatePem,
    { algorithm: 'RS256', expiresIn: '5m' },
  );
}

beforeAll(async () => {
  vi.stubEnv('NODE_ENV', 'test');
  configureAuth({ enableTestTokens: false, defaultTenantId: 'ten-1', securityServiceUrl: 'http://security.test' });
  const app = express();
  // The shape proxy.ts mounts eight times: authenticate → attach → require.
  app.get('/gated', authenticateToken(true), attachScopes, requireScope('webhooks:manage'), (req, res) => {
    const u = (req as unknown as { user: { authMethod?: string; scopes?: string[] } }).user;
    res.json({ ok: true, authMethod: u.authMethod ?? null, scopes: u.scopes ?? null });
  });
  await new Promise<void>((resolve) => { server = app.listen(0, '127.0.0.1', resolve); });
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});
afterAll(async () => { vi.unstubAllEnvs(); await new Promise<void>((resolve) => server.close(() => resolve())); });
beforeEach(() => { apiKeyCache.clear(); fetchMock.mockReset(); });

type GateBody = { ok?: boolean; authMethod?: string | null; scopes?: string[] | null; required?: string[]; granted?: string[] };
const call = (headers: Record<string, string>) => realFetch(`${base}/gated`, { headers });
const bodyOf = async (r: Response) => (await r.json()) as GateBody;

describe('KS-835 — the gate reads the OAuth label and the granted scopes', () => {
  it('an OAuth token granted only `openid` is REFUSED at a route requiring webhooks:manage — 403 naming what was granted', async () => {
    const r = await call({ authorization: `Bearer ${sign({ authMethod: 'oauth', scopes: ['openid'], client_id: 'client-835' })}` });
    expect(r.status).toBe(403);
    const body = await bodyOf(r);
    expect(body.required).toEqual(['webhooks:manage']);
    expect(body.granted).toEqual(['openid']);
  });

  it('CONTROL — the same token shape WITH webhooks:manage granted passes (the route itself is fine)', async () => {
    const r = await call({ authorization: `Bearer ${sign({ authMethod: 'oauth', scopes: ['webhooks:manage'], client_id: 'client-835' })}` });
    expect(r.status).toBe(200);
    const body = await bodyOf(r);
    expect(body.authMethod).toBe('oauth');
    expect(body.scopes).toEqual(['webhooks:manage']);
  });

  it('CONTROL — an sk_* API key with the same narrow scope is refused too (the gate, not the OAuth path, is what refuses)', async () => {
    fetchMock.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ data: { valid: true, connectorId: 'c835', scopes: ['openid'], organizationId: 'org-1', rateLimit: 100, rateLimitWindow: 60 } }),
    });
    const r = await call({ 'x-api-key': 'sk_narrow_835' });
    expect(r.status).toBe(403);
    expect((await bodyOf(r)).granted).toEqual(['openid']);
  });

  it('the mechanism the ticket named, pinned: an UNLABELLED token with the same narrow scopes is short-circuited (a login is governed by RBAC, not scopes)', async () => {
    const r = await call({ authorization: `Bearer ${sign({ scopes: ['openid'] })}` });
    expect(r.status).toBe(200); // by design for logins; the OAuth path now carries the label so it does NOT land here
  });

  it('an OAuth token with NO scopes claim at all is refused (nothing granted, nothing allowed)', async () => {
    const r = await call({ authorization: `Bearer ${sign({ authMethod: 'oauth', client_id: 'client-835' })}` });
    expect(r.status).toBe(403);
    expect((await bodyOf(r)).granted).toEqual([]);
  });

  it('H3 (attachScopes): a token\'s scopes ARRAY is left alone; a legacy singular `scope` string is accepted only when no array is present', () => {
    const next = vi.fn();
    const withArray = { user: { authMethod: 'oauth', scopes: ['openid'], scope: 'webhooks:manage' } } as unknown as express.Request;
    attachScopes(withArray, {} as express.Response, next);
    expect((withArray as unknown as { user: { scopes: string[] } }).user.scopes).toEqual(['openid']); // the array wins; the string never widens it
    const legacy = { user: { authMethod: 'oauth', scope: 'a:read b:write' } } as unknown as express.Request;
    attachScopes(legacy, {} as express.Response, next);
    expect((legacy as unknown as { user: { scopes: string[] } }).user.scopes).toEqual(['a:read', 'b:write']);
    const bare = { user: { authMethod: 'oauth' } } as unknown as express.Request;
    attachScopes(bare, {} as express.Response, next);
    expect((bare as unknown as { user: { scopes?: string[] } }).user.scopes).toBeUndefined();
    expect(next).toHaveBeenCalledTimes(3);
  });
});
